class Task {

    private static int mod = 998244353;

    public long powMod(long a, long b) {
        long ans = 1, d = a;
        while (b > 0) {
            if (b % 2 == 1) ans = ans * d % mod;
            b >>= 1;
            d = d * d % mod;
        }
        return ans;
    }

    long[] fac, inv;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        //int T = in.nextInt();
        int n = 200001;
        fac = new long[n];
        inv = new long[n];
        fac[0] = inv[0] = 1;
        for (int i = 1; i < n; i++) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = inv[i - 1] * powMod(i, mod - 2) % mod;
        }
        //for (int tc = 1; tc <= T; tc++) {
            n = in.nextInt();
            long k = in.nextLong();
            if (k >= n) {
                out.println(0);
                return;
            }
            if (k == 0) {
                out.println(fac[n]);
                return;
            }
            int m = (int)(n - k);
            long ans = 0;
            for (int i = 0; i <= m; i++) {
                if (i % 2 == 0) {
                    ans = (ans + getC(m, i) * powMod(m - i, n) % mod) % mod;
                } else {
                    ans = ((ans - getC(m, i) * powMod(m - i, n) % mod) % mod + mod) % mod;
                }
            }
            out.println(2 * fac[n] * inv[n - m] % mod * ans % mod * inv[m] % mod);
        //}
    }

    private long getC(int n, int m) {
        return fac[n] * inv[m] % mod * inv[n - m] % mod;
    }

}

class InputReader {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
        tokenizer = null;
    }

    public String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(nextLine());
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

}

